# Let's inspect the exact position of all objects on the table using language segmentation / point clouds
obj_names = ["can", "basket", "milk", "sauce", "pudding", "butter"]
for name in obj_names:
    res = primitives.call(
        name="submit_capx_action",
        action="get_object_3d_points_and_masks_from_language",
        native_api=True,
        parameters={"text_prompt": name, "use_multiview": False}
    )
    if res.ok:
        pts = res.output.get("native_api_result", {}).get("points_3d")
        obb = primitives.call(
            name="submit_capx_action",
            action="get_oriented_bounding_box_from_3d_points",
            native_api=True,
            parameters={"points": pts}
        )
        if obb.ok:
            center = obb.output.get("native_api_result", {}).get("center", {}).get("values")
            print(f"{name} center: {center}")
